package com.mohamedrejeb.richeditor.sample.common.htmleditor

import androidx.compose.foundation.layout.*
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material.icons.filled.SwapHoriz
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.TextFieldValue
import androidx.compose.ui.unit.dp
import cafe.adriel.voyager.navigator.LocalNavigator
import com.mohamedrejeb.richeditor.model.rememberRichTextState

@OptIn(ExperimentalMaterial3Api::class, ExperimentalLayoutApi::class)
@Composable
fun HtmlEditorContent() {
    val navigator = LocalNavigator.current

    var isHtmlToRichText by remember { mutableStateOf(false) }

    var html1 by remember {
        mutableStateOf(TextFieldValue("<div class=\"BodyFragment\"><font size=\"2\"><span style=\"font-size:10pt\">\n" +
                "<div class=\"PlainText\" style=\"background-color: #EBEBEB;\">This is a jpeg<br>\n" +
                "</div>\n" +
                "</span></font></div>\n" +
                "<div><img src=\"data:image/jpeg;base64,\"> </div>\n" +
                "<div class=\"BodyFragment\"><font size=\"2\"><span style=\"font-size:10pt\">\n" +
                "<div class=\"PlainText\" style=\"background-color: #ABBAEA;\"><br>\n" +
                "And this is png<br>\n" +
                "</div>\n" +
                "</span></font></div>\n" +
                "<div><img src=\"data:image/png;base64,\"> </div>\n" +
                "<div class=\"BodyFragment\"><font size=\"2\"><span style=\"font-size:10pt\">\n" +
                "<div class=\"PlainText\" style=\"background-color: #FBD603;\"><br>\n" +
                "And this is gif<br>\n" +
                "</div>\n" +
                "</span></font></div>\n" +
                "<div><img src=\"data:image/gif;base64,R0lGODlhEAAQAKIHAP39MvK3BP7+Tf3hDv//3f//mv///////yH5BAEAAAcALAAAAAAQABAAAANWeLonwhAKEKsoY1RpQNiMYAyfNAFoYQQD6gJCG8xiABMF0B6qIcwsg9CjUQgIwhOJRTG1AIXJxlNTPSo2YctAuDJQXIdNCml1F8ymggSDzNSHzGZ3SAAAOw==\"> </div>"))
    }

    var html by remember {
        mutableStateOf(TextFieldValue("<div class=\"BodyFragment\"><font size=\"2\"><span style=\"font-size:10pt\">\n" +
                "<div class=\"PlainText\" style=\"background-color: #EBEBEB;\">This is a jpeg<br>\n" +
                "</div>\n" +
                "</span></font></div>\n" +
                "<div><img src=\"data:image/jpeg;base64,\"> </div>\n" +
                "<div class=\"BodyFragment\"><font size=\"2\"><span style=\"font-size:10pt\">\n" +
                "<div class=\"PlainText\" style=\"background-color: #FBD603;\"><br>\n" +
                "And this is gif<br>\n" +
                "</div>\n" +
                "</span></font></div>\n" +
                "<div><img src=\"data:image/gif;base64,R0lGODlhEAAQAKIHAP39MvK3BP7+Tf3hDv//3f//mv///////yH5BAEAAAcALAAAAAAQABAAAANWeLonwhAKEKsoY1RpQNiMYAyfNAFoYQQD6gJCG8xiABMF0B6qIcwsg9CjUQgIwhOJRTG1AIXJxlNTPSo2YctAuDJQXIdNCml1F8ymggSDzNSHzGZ3SAAAOw==\"> </div>"))
    }
    val richTextState = rememberRichTextState()

    LaunchedEffect(richTextState.annotatedString, isHtmlToRichText) {
        if (!isHtmlToRichText) {
            richTextState.setHtml(html.text)
//            html = TextFieldValue(richTextState.toHtml())
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Html Editor") },
                navigationIcon = {
                    IconButton(
                        onClick = { navigator?.pop() }
                    ) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                actions = {
                    IconButton(
                        onClick = {
                            isHtmlToRichText = !isHtmlToRichText
                        }
                    ) {
                        Icon(
                            imageVector = Icons.Filled.SwapHoriz,
                            contentDescription = "Swap",
                        )
                    }
                }
            )
        },
        containerColor = MaterialTheme.colorScheme.background,
        contentColor = MaterialTheme.colorScheme.onBackground,
        modifier = Modifier
            .fillMaxSize()
            .imePadding()
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .padding(paddingValues)
                .windowInsetsPadding(WindowInsets.ime)
                .fillMaxSize()
        ) {
            if (isHtmlToRichText) {
                HtmlToRichText(
                    html = html,
                    onHtmlChange = {
                        html = it
                        richTextState.setHtml(it.text)
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                )
            } else {
                RichTextToHtml(
                    richTextState = richTextState,
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                )
            }
        }
    }
}